# Let me look more systematically at how Treasury Bulletin typically presents this data
# I'll search for any occurrence of "1960" through "1969" specifically in yield contexts

with open('/app/resources/treasury_bulletin_1970_06.txt', 'r') as f:
    lines = f.readlines()

# Search for any year labels in the entire document
years_found = {}
for i, line in enumerate(lines):
    for year in range(1960, 1975):
        if str(year) in line and ('bond' in line.lower() or 'yield' in line.lower() or 'percent' in line.lower()):
            if year not in years_found:
                years_found[year] = []
            years_found[year].append((i, line[:100]))

print("Years found near bond/yield data:")
for year, occurrences in sorted(years_found.items()):
    print(f"\n{year}:")
    for line_num, line in occurrences[:3]:
        print(f"  Line {line_num}: {line}")
