# Let me calculate the average spread for each year (column group) properly
import re

with open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r') as f:
    content = f.read()

table_match = re.search(r'<table>(.*?)</table>', content, re.DOTALL)
if table_match:
    table = table_match.group(1)
    rows = re.findall(r'<tr>(.*?)</tr>', table, re.DOTALL)

    spreads_by_group = {1: [], 2: [], 3: [], 4: []}

    for row in rows:
        month_match = re.search(r'<td>(Jan|Feb|Mar|Apr|May|June|July|Aug|Sept|Oct|Nov|Dec)\.?</td>', row)
        if month_match:
            cells = re.findall(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)

            if len(cells) >= 12:
                def clean_val(s):
                    s = re.sub(r'\s*\d+/', '', s.strip())
                    try:
                        return float(s)
                    except:
                        return None

                # Group 1: cols 1-2, Group 2: cols 4-5, Group 3: cols 7-8, Group 4: cols 10-11
                t1, c1 = clean_val(cells[1]), clean_val(cells[2])
                t2, c2 = clean_val(cells[4]), clean_val(cells[5])
                t3, c3 = clean_val(cells[7]), clean_val(cells[8])
                t4, c4 = clean_val(cells[10]), clean_val(cells[11])

                if t1 and c1: spreads_by_group[1].append(c1 - t1)
                if t2 and c2: spreads_by_group[2].append(c2 - t2)
                if t3 and c3: spreads_by_group[3].append(c3 - t3)
                if t4 and c4: spreads_by_group[4].append(c4 - t4)

    # Print results
    print("Average spread by column group:")
    for g, spreads in spreads_by_group.items():
        if spreads:
            avg = sum(spreads) / len(spreads)
            print(f"Group {g}: {len(spreads)} months, avg spread = {avg:.4f}%")

    # Overall average
    all_spreads = spreads_by_group[1] + spreads_by_group[2] + spreads_by_group[3] + spreads_by_group[4]
    if all_spreads:
        overall = sum(all_spreads) / len(all_spreads)
        print(f"\nOverall average: {overall:.5f}%")
        print(f"With 5 significant digits: {overall:.5f}")
