# Let me do a more detailed check on the actual values to make sure my calculation is correct

import re

with open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r') as f:
    content = f.read()

table_match = re.search(r'<table>(.*?)</table>', content, re.DOTALL)
if table_match:
    table = table_match.group(1)
    rows = re.findall(r'<tr>(.*?)</tr>', table, re.DOTALL)

    all_data = []

    for row in rows:
        month_match = re.search(r'<td>(Jan|Feb|Mar|Apr|May|June|July|Aug|Sept|Oct|Nov|Dec)\.?</td>', row)
        if month_match:
            cells = re.findall(r'<td[^>]*>(.*?)</td>', row, re.DOTALL)

            if len(cells) >= 12:
                def clean_val(s):
                    s = re.sub(r'\s*\d+/', '', s.strip())
                    try:
                        return float(s)
                    except:
                        return None

                # Extract all 4 groups
                row_data = []
                for grp in [(1,2), (4,5), (7,8), (10,11)]:
                    t_idx, c_idx = grp
                    t = clean_val(cells[t_idx])
                    c = clean_val(cells[c_idx])
                    if t is not None and c is not None:
                        row_data.append((t, c, c-t))

                if row_data:
                    month = month_match.group(1)
                    all_data.append((month, row_data))

    # Print detailed breakdown
    print("Month-by-month spreads for each column group:")
    for month, groups in all_data[:3]:
        print(f"\n{month}:")
        for i, (t, c, s) in enumerate(groups):
            print(f"  Group {i+1}: Treasury={t}, Aa Corporate={c}, Spread={s:.4f}")

    # Calculate correctly - average across all individual spreads
    all_spreads = []
    for month, groups in all_data:
        for t, c, s in groups:
            all_spreads.append(s)

    print(f"\n\nTotal number of spread values: {len(all_spreads)}")
    print(f"Average spread: {sum(all_spreads)/len(all_spreads):.5f}")

    # Round to 5 significant digits
    avg = sum(all_spreads)/len(all_spreads)
    print(f"5 significant digits: {avg:.5f}")
